src/idle.js
const IDLE_TIMEOUT = 30;

function isIdle(session, now) {
  return session.lastSeen + IDLE_TIMEOUT < now;
}

module.exports = { isIdle, IDLE_TIMEOUT };
src/backoff.js
const SECOND = 1000;

function reconnectDelay(attempt) {
  return Math.min(30 * SECOND, SECOND * 2 ** attempt);
}

module.exports = { reconnectDelay };
src/sweep.js
const { isIdle } = require('./idle');

function sweep(store, now) {
  const kept = {};
  for (const [id, session] of Object.entries(store)) {
    if (!isIdle(session, now)) kept[id] = session;
  }
  return kept;
}

module.exports = { sweep };
